def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If alone, bid enough to cover requirement safely.
    if not alive_opps:
        bid = DAILY_SALARY * 0.45
        return float(min(my_budget, bid))

    # Use only yesterday's immediate trace bids to gauge market pressure.
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are effectively available.
    # supply is in same scale as WATER_REQ; use float->int for safety.
    units_available = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0

    # Base urgency from my hp and no-water streak.
    urgency = 0.0
    if my_hp <= 2.0:
        urgency += 1.0
    elif my_hp <= 4.0:
        urgency += 0.7
    else:
        urgency += 0.3

    if my_no_water_days >= 2:
        urgency += 0.5
    elif my_no_water_days == 1:
        urgency += 0.2

    # Adjust bid relative to yesterday's max bid.
    # If others were bidding extremely high, we must compete; otherwise bid moderately.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        pressure = 0.7
    elif highest_prev_bid > 0.0:
        pressure = 0.4
    else:
        pressure = 0.25

    # If supply is low (near MIN_SUPPLY), slightly increase to avoid being the only one without water.
    supply_factor = 0.0
    if supply <= float(MIN_SUPPLY) + 1e-9:
        supply_factor = 0.15
    elif supply <= float(MIN_SUPPLY) + 4.0:
        supply_factor = 0.08
    else:
        supply_factor = 0.0

    # Compute target bid.
    # Keep it under a cap to preserve budget, but react to pressure.
    if pressure >= 0.9:
        target = DAILY_SALARY * (0.35 + 0.35 * urgency + supply_factor)
        # Nudge above yesterday's highest bid if we are very low hp.
        if my_hp <= 3.0:
            target = max(target, highest_prev_bid + 2.0)
    elif pressure >= 0.6:
        target = DAILY_SALARY * (0.45 + 0.25 * urgency + supply_factor)
        if my_hp <= 3.0:
            target = max(target, highest_prev_bid * 0.9)
    else:
        # Moderate bid: aim to secure water when possible.
        target = DAILY_SALARY * (0.50 + 0.20 * urgency + supply_factor)
        # If supply seems sufficient (units_available >=1), we can bid a bit less.
        if units_available >= 1:
            target *= 0.95

    # Ensure feasibility with budget and avoid bidding too low when critical.
    min_critical = DAILY_SALARY * (0.75 if my_hp <= 2.0 else 0.55)
    if my_hp <= 2.0 or my_no_water_days >= 2:
        target = max(target, min_critical)

    # Final clamp.
    if my_budget <= 0:
        return 0.0

    bid = float(min(my_budget, max(0.0, target)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('budget', 0) > budget:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive_opps:
        return float(min(budget, 18.0))

    high_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    very_tight = supply <= 17
    tight = supply <= 19
    abundant = supply >= 23

    if hp <= 2 or no_water >= 2:
        bid = max(0.96 * DAILY_SALARY, high_prev + 3.0)
        return float(min(budget, bid))

    if hp <= 4 or no_water >= 1:
        bid = max(0.82 * DAILY_SALARY, high_prev + 2.0)
        if very_tight:
            bid = max(bid, 0.92 * DAILY_SALARY)
        return float(min(budget, bid))

    if day >= 8:
        bid = max(0.68 * DAILY_SALARY, avg_prev + 2.0)
        if tight:
            bid = max(bid, high_prev + 1.5)
        return float(min(budget, bid))

    if abundant and hp >= 7 and no_water == 0:
        bid = 0.18 * DAILY_SALARY
        if high_prev < 20:
            bid = 12.0
        return float(min(budget, bid))

    if very_tight:
        bid = max(0.72 * DAILY_SALARY, high_prev + 1.5)
        if urgent_opp >= 2:
            bid += 4.0
        if rich_opp >= 1:
            bid += 2.0
        return float(min(budget, bid))

    if tight:
        bid = max(0.55 * DAILY_SALARY, avg_prev + 1.0)
        if high_prev >= 80:
            bid = 0.42 * DAILY_SALARY
        return float(min(budget, bid))

    bid = 0.34 * DAILY_SALARY
    if high_prev >= 85:
        bid = 0.24 * DAILY_SALARY
    elif high_prev >= 60:
        bid = 0.30 * DAILY_SALARY
    elif high_prev > 0:
        bid = max(bid, min(0.46 * DAILY_SALARY, avg_prev * 0.7))

    return float(min(budget, bid))
